import { Button } from "@/registry/erbium/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/registry/erbium/ui/popover";

export function PopoverBasic() {
  return (
    <>
      <Popover>
        <PopoverTrigger render={<Button variant="outline" className="w-fit" />}>
          Open Popover
        </PopoverTrigger>
        <PopoverContent align="start">
          <PopoverHeader>
            <PopoverTitle>Dimensions</PopoverTitle>
            <PopoverDescription>Set the dimensions for the layer.</PopoverDescription>
          </PopoverHeader>
        </PopoverContent>
      </Popover>
    </>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { Field, FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/registry/erbium/ui/popover";

export function PopoverForm() {
  return (
    <>
      <Popover>
        <PopoverTrigger render={<Button variant="outline" />}>Open Popover</PopoverTrigger>
        <PopoverContent className="w-64" align="start">
          <PopoverHeader>
            <PopoverTitle>Dimensions</PopoverTitle>
            <PopoverDescription>Set the dimensions for the layer.</PopoverDescription>
          </PopoverHeader>
          <FieldGroup className="gap-4">
            <Field orientation="horizontal">
              <FieldLabel className="w-1/2">Width</FieldLabel>
              <Input defaultValue="100%" />
            </Field>
            <Field orientation="horizontal">
              <FieldLabel className="w-1/2">Height</FieldLabel>
              <Input defaultValue="25px" />
            </Field>
          </FieldGroup>
        </PopoverContent>
      </Popover>
    </>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { Popover } from "@/registry/erbium/ui/popover";

import type { Meta, StoryObj } from "@storybook/react";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import {\n  Popover,\n  PopoverTrigger,\n  PopoverContent,\n  PopoverHeader,\n  PopoverTitle,\n  PopoverDescription,\n} from \"@/registry/erbium/ui/popover\";\nimport { Button } from \"@/registry/erbium/ui/button\";\n\nconst Example = (args: {\n  side: \"top\" | \"right\" | \"bottom\" | \"left\";\n  align: \"start\" | \"center\" | \"end\";\n  defaultOpen: boolean;\n}) => (\n  <Popover key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>\n    <PopoverTrigger render={<Button variant=\"outline\">Open popover</Button>} />\n    <PopoverContent side={args.side} align={args.align}>\n      <PopoverHeader>\n        <PopoverTitle>Popover title</PopoverTitle>\n        <PopoverDescription>Popover description.</PopoverDescription>\n      </PopoverHeader>\n    </PopoverContent>\n  </Popover>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/popover-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import BasicExample from "./variants/basic";

const BasicSource = "import { PopoverBasic } from \"../examples/popover-basic\";\n\nconst Example = () => <PopoverBasic />;\n\nexport default Example;\n";

import AlignExample from "./variants/align";

const AlignSource = "import { PopoverAlignments } from \"../examples/popover-alignments\";\n\nconst Example = () => <PopoverAlignments />;\n\nexport default Example;\n";

import WithFormExample from "./variants/with-form";

const WithFormSource = "import { PopoverForm } from \"../examples/popover-form\";\n\nconst Example = () => <PopoverForm />;\n\nexport default Example;\n";

const meta = {
  component: Popover,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nOpen rich content in a portal from a button trigger.\n\n**Import:** `@/registry/erbium/ui/popover`\n\n## Usage\n\n```tsx\nimport {\n  Popover,\n  PopoverContent,\n  PopoverDescription,\n  PopoverHeader,\n  PopoverTitle,\n  PopoverTrigger,\n} from \"@/registry/erbium/ui/popover\"\nimport {{ Button }} from \"@/registry/erbium/ui/button\"\n```\n\n```tsx\n<Popover>\n  <PopoverTrigger render={<Button variant=\"outline\" />}>Open Popover</PopoverTrigger>\n  <PopoverContent>\n    <PopoverHeader>\n      <PopoverTitle>Title</PopoverTitle>\n      <PopoverDescription>Description text here.</PopoverDescription>\n    </PopoverHeader>\n  </PopoverContent>\n</Popover>\n```\n\n## Composition\n\nUse the following composition to build a `Popover`:\n\n```text\nPopover\n├── PopoverTrigger\n└── PopoverContent\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Popover](https://base-ui.com/react/components/popover)",
      },
    },
  },
} satisfies Meta<typeof Popover>;

export default { ...meta, title: "Overlays & menus/Popover",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  side: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
  defaultOpen: boolean;
}> = {
  args: { side: "bottom", align: "center", defaultOpen: false },
  argTypes: {
    side: { control: "select", options: ["top", "right", "bottom", "left"] },
    align: { control: "select", options: ["start", "center", "end"] },
    defaultOpen: { control: "boolean" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Basic: Story = {
  parameters: {
    docs: {
      description: { story: "A simple popover with a header, title, and description." },
      source: { code: BasicSource },
    },
  },
  render: BasicExample,
};

export const Align: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `align` prop on `PopoverContent` to control the horizontal alignment." },
      source: { code: AlignSource },
    },
  },
  render: AlignExample,
};

export const WithForm: Story = {
  parameters: {
    docs: {
      description: { story: "A popover with form fields inside." },
      source: { code: WithFormSource },
    },
  },
  render: WithFormExample,
};

import { PopoverAlignments } from "../examples/popover-alignments";

const Example = () => <PopoverAlignments />;

export default Example;

import { PopoverBasic } from "../examples/popover-basic";

const Example = () => <PopoverBasic />;

export default Example;

import Demo from "../examples/popover-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

import {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverHeader,
  PopoverTitle,
  PopoverDescription,
} from "@/registry/erbium/ui/popover";
import { Button } from "@/registry/erbium/ui/button";

const Example = (args: {
  side: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
  defaultOpen: boolean;
}) => (
  <Popover key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>
    <PopoverTrigger render={<Button variant="outline">Open popover</Button>} />
    <PopoverContent side={args.side} align={args.align}>
      <PopoverHeader>
        <PopoverTitle>Popover title</PopoverTitle>
        <PopoverDescription>Popover description.</PopoverDescription>
      </PopoverHeader>
    </PopoverContent>
  </Popover>
);

export default Example;

import { PopoverForm } from "../examples/popover-form";

const Example = () => <PopoverForm />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}
